import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { boundedFetch } from '../../../functions/_shared/boundedFetch.ts';
import { createNotificationEventDispatcher } from './handler.ts';

const projectUrl = Deno.env.get('SUPABASE_URL') ?? '';
const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
const service = createClient(projectUrl, serviceKey, {
  auth: { persistSession: false, autoRefreshToken: false }, global: { fetch: boundedFetch(fetch) },
});
Deno.serve(createNotificationEventDispatcher({
  projectUrl, serviceKey, fetch: boundedFetch(fetch),
  claim: (jobId, token, signal) => service.rpc('claim_notification_event_dispatch', {
    p_job_id: jobId, p_token: token,
  }).abortSignal(signal),
  allowed: (jobId, claimId, signal) => service.rpc('notification_event_dispatch_allowed', {
    p_job_id: jobId, p_claim_id: claimId,
  }).abortSignal(signal),
  finish: (jobId, claimId, outcome, signal) => service.rpc('finish_notification_event_dispatch', {
    p_job_id: jobId, p_claim_id: claimId, p_outcome: outcome,
  }).abortSignal(signal),
}));

import { boundedPushJson, pushResponse, validUuid, waitForPush } from '../../../functions/_shared/pushDelivery.ts';

type Claim = { claimId: string; kind: 'notification' | 'call'; eventId: string };
type Outcome = 'accepted' | 'skipped' | 'failed' | 'unknown';
type Dependencies = {
  projectUrl: string; serviceKey: string; fetch: typeof fetch; deadlineMs?: number;
  claim: (jobId: string, token: string, signal: AbortSignal) => PromiseLike<{ data: unknown; error: unknown }>;
  allowed: (jobId: string, claimId: string, signal: AbortSignal) => PromiseLike<{ data: unknown; error: unknown }>;
  finish: (jobId: string, claimId: string, outcome: Outcome, signal: AbortSignal) => PromiseLike<{ data: unknown; error: unknown }>;
};
const QA_ORIGIN = 'https://uaulhuelcfkjwojtymmw.supabase.co';
const validClaim = (value: unknown): value is Claim => {
  if (!value || typeof value !== 'object') return false;
  const claim = value as Claim;
  return validUuid(claim.claimId) && validUuid(claim.eventId) && ['notification', 'call'].includes(claim.kind);
};

/** The exposed queue capability can only consume one existing canonical event.
 * The service credential remains within Edge and its fixed same-project calls. */
export function createNotificationEventDispatcher(deps: Dependencies) {
  return async (request: Request): Promise<Response> => {
    if (request.method !== 'POST') return pushResponse(405, { error: 'Method not allowed' });
    if (deps.projectUrl !== QA_ORIGIN || deps.serviceKey.length < 32) return pushResponse(503, { error: 'Event dispatcher unavailable' });
    const signal = AbortSignal.any([request.signal, AbortSignal.timeout(deps.deadlineMs ?? 30_000)]);
    let jobId: string | null = null, claim: Claim | null = null, outcome: Outcome = 'unknown';
    try {
      if (signal.aborted) throw new Error('ABORTED');
      let body: Record<string, unknown>;
      try { body = await boundedPushJson(request, signal, 1024); }
      catch { return pushResponse(401, { error: 'Event authorization required' }); }
      if (Object.keys(body).sort().join(',') !== 'jobId,token' || !validUuid(body.jobId)
        || typeof body.token !== 'string' || !/^[a-f0-9]{64}$/.test(body.token)) {
        return pushResponse(401, { error: 'Event authorization required' });
      }
      jobId = body.jobId;
      const result = await waitForPush(deps.claim(jobId, body.token, signal), signal);
      if (result.error) throw new Error('CLAIM_UNAVAILABLE');
      if (!validClaim(result.data)) return pushResponse(401, { error: 'Event authorization unavailable' });
      claim = result.data;
      if (signal.aborted) throw new Error('ABORTED');
      const permission = await waitForPush(deps.allowed(jobId, claim.claimId, signal), signal);
      if (permission.error) throw new Error('RECHECK_UNAVAILABLE');
      if (permission.data !== true) { outcome = 'skipped'; throw new Error('EVENT_PAUSED'); }
      if (signal.aborted) throw new Error('ABORTED');
      const target = claim.kind === 'call' ? 'send-voip-push' : 'send-push-notification';
      const payload = claim.kind === 'call' ? { callId: claim.eventId } : { record: { id: claim.eventId } };
      const response = await waitForPush(deps.fetch(`${QA_ORIGIN}/functions/v1/${target}`, {
        method: 'POST', redirect: 'error', signal,
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${deps.serviceKey}` },
        body: JSON.stringify(payload),
      }), signal);
      if (!response.ok) { void response.body?.cancel().catch(() => {}); throw new Error('DOWNSTREAM_UNKNOWN'); }
      const receipt = await boundedPushJson(response, signal, 4096);
      const count = (key: string) => typeof receipt[key] === 'number' && Number.isSafeInteger(receipt[key]) && Number(receipt[key]) >= 0;
      if (receipt.skipped === true) outcome = 'skipped';
      else if (count('accepted') && count('rejected') && count('unknown')) {
        outcome = Number(receipt.unknown) > 0 ? 'unknown' : Number(receipt.accepted) > 0 ? 'accepted'
          : Number(receipt.rejected) > 0 ? 'failed' : 'skipped';
      }
    } catch { /* A consumed event is never automatically retried after uncertainty. */ }
    if (jobId && claim) {
      try {
        const completionSignal = AbortSignal.timeout(3000);
        const result = await waitForPush(deps.finish(jobId, claim.claimId, outcome, completionSignal), completionSignal);
        if (result.error || result.data !== true) return pushResponse(503, { error: 'Inspect the event delivery status before retrying' });
      } catch { return pushResponse(503, { error: 'Inspect the event delivery status before retrying' }); }
      return pushResponse(outcome === 'accepted' || outcome === 'skipped' ? 202 : 502, { outcome });
    }
    return pushResponse(503, { error: 'Event delivery is temporarily unavailable' });
  };
}

// One bounded network operation, including response-body consumption. Preserve
// both the caller cancellation and any timeout/signal supplied by the SDK.
export function boundedFetch(fetcher: typeof fetch, parent?: AbortSignal, deadlineMs = 8000): typeof fetch {
  return (input, init) => {
    const signals: AbortSignal[] = [AbortSignal.timeout(deadlineMs)];
    if (parent) signals.push(parent);
    const initSignal = (init as { signal?: AbortSignal | null } | undefined)?.signal;
    if (initSignal) signals.push(initSignal);
    if (input instanceof Request) signals.push(input.signal);
    return fetcher(input, { ...init, signal: AbortSignal.any(signals) });
  };
}

export const PUSH_HEADERS = { 'Content-Type': 'application/json', 'Cache-Control': 'private, no-store',
  'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
  'Access-Control-Allow-Methods': 'POST, OPTIONS' };
export const pushResponse = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: PUSH_HEADERS });
export const validUuid = (value: unknown): value is string => typeof value === 'string'
  && /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(value);
export const validExpoToken = (value: unknown): value is string => typeof value === 'string'
  && /^(ExpoPushToken|ExponentPushToken)\[[A-Za-z0-9_-]{1,200}\]$/.test(value);

export async function servicePushAuthorized(request: Request, key: string): Promise<boolean> {
  const supplied = /^Bearer ([^\s]+)$/i.exec(request.headers.get('Authorization') || '')?.[1];
  if (!supplied || key.length < 32 || supplied.length > 4096) return false;
  const digest = async (value: string) => new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value)));
  const [a, b] = await Promise.all([digest(supplied), digest(key)]);
  let difference = 0;
  for (let i = 0; i < a.length; i++) difference |= a[i] ^ b[i];
  return difference === 0;
}

export function waitForPush<T>(work: PromiseLike<T>, signal: AbortSignal): Promise<T> {
  return new Promise((resolve, reject) => {
    const expired = () => reject(new Error('PUSH_DEADLINE'));
    if (signal.aborted) { void Promise.resolve(work).catch(() => {}); expired(); return; }
    signal.addEventListener('abort', expired, { once: true });
    Promise.resolve(work).then(value => { signal.removeEventListener('abort', expired); resolve(value); },
      error => { signal.removeEventListener('abort', expired); reject(error); });
  });
}

export async function boundedPushJson(input: Request | Response, signal: AbortSignal, maximum = 65_536): Promise<Record<string, unknown>> {
  const reader = input.body?.getReader();
  if (!reader) throw new Error('EMPTY_REQUEST');
  let bytes = 0, text = '';
  const decoder = new TextDecoder();
  const abort = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener('abort', abort, { once: true });
  try {
    while (true) {
      if (signal.aborted) throw new Error('PUSH_DEADLINE');
      const { done, value } = await waitForPush(reader.read(), signal);
      if (done) break;
      bytes += value.byteLength;
      if (bytes > maximum) throw new Error('REQUEST_TOO_LARGE');
      text += decoder.decode(value, { stream: true });
    }
    text += decoder.decode();
    const value = JSON.parse(text);
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('INVALID_REQUEST');
    return value;
  } finally { signal.removeEventListener('abort', abort); void reader.cancel().catch(() => {}); try { reader.releaseLock(); } catch { /* A cancelled read already released the stream. */ } }
}

export type ExpoPushMessage = { to: string; [key: string]: unknown };
export type ExpoPushResult = { accepted: number; rejected: number; unknown: number;
  tickets: { token: string; id: string }[]; invalidTokens: string[] };

/** Expo acceptance is a queue ticket, never a claim of delivery to a phone. */
export async function sendExpoPushes(messages: ExpoPushMessage[], options: {
  fetch: typeof fetch; signal: AbortSignal; accessToken?: string;
  maySend?: () => Promise<boolean>;
}): Promise<ExpoPushResult> {
  const result: ExpoPushResult = { accepted: 0, rejected: 0, unknown: 0, tickets: [], invalidTokens: [] };
  for (let offset = 0; offset < messages.length; offset += 100) {
    if (options.signal.aborted || (options.maySend && !await options.maySend())) {
      result.rejected += messages.length - offset; break;
    }
    const batch = messages.slice(offset, offset + 100);
    try {
      const response = await waitForPush(options.fetch('https://exp.host/--/api/v2/push/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json',
          ...(options.accessToken ? { Authorization: `Bearer ${options.accessToken}` } : {}) },
        body: JSON.stringify(batch), redirect: 'error', signal: options.signal,
      }), options.signal);
      const body = await boundedPushJson(response, options.signal);
      if (!response.ok || !Array.isArray(body.data) || body.data.length !== batch.length) {
        result.unknown += batch.length; continue;
      }
      body.data.forEach((ticket: { status?: string; id?: string; details?: { error?: string } }, index: number) => {
        if (ticket?.status === 'ok' && typeof ticket.id === 'string' && ticket.id.length <= 200) {
          result.accepted++; result.tickets.push({ token: batch[index].to, id: ticket.id });
        } else if (ticket?.status === 'error') {
          result.rejected++;
          if (ticket.details?.error === 'DeviceNotRegistered') result.invalidTokens.push(batch[index].to);
        } else result.unknown++;
      });
    } catch { result.unknown += batch.length; }
  }
  return result;
}
